    return .{ .transformed = .{ .replacement = ast.refusal(allocator, reporter, .KORU161, flow.location, flow.module, "std/store:sweep({s}): exactly one `! sweep <row>` branch per site", .{store_name}) } };
}
const sc = &flow.body.continuations[0];
if (!std.mem.eql(u8, std.mem.trim(u8, sc.branch, " "), "sweep")) {
    return .{ .transformed = .{ .replacement = ast.refusal(allocator, reporter, .KORU161, flow.location, flow.module, "std/store:sweep({s}): the row branch is spelled `! sweep <row>`", .{store_name}) } };
