    return .{ .transformed = .{ .replacement = ast.refusal(allocator, reporter, .KORU161, flow.location, flow.module, "std/store:sweep({s}): the sweep arm binds its row - write `! sweep <row> |> ... <row>.<field> ...`, not a projection block", .{store_name}) } };
}
